def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def sa_search(budget):
        x = rng.uniform(-5, 5, size=dim)
        T = 1000.0
        for i in range(1, budget+1):
            y = x + rng.normal(size=x.shape) * (ub - lb) / 3.0
            y = clip(y)
            if func(y) < func(x):
                x = y
            else:
                s = np.exp(-i/T)
                u = rng.uniform(0, 1)
                if u < s:
                    x = y
        return x

    def cma_es_search(budget):
        mu = ub - lb
        sigma = (ub - lb) / 2.0
        lambda_ = 100
        x = rng.normal(size=dim)
        for i in range(1, budget+1):
            y = x + rng.normal(size=x.shape) * sigma
            y = clip(y)
            fx = func(y)
            f = np.full(lambda_, np.inf)
            idx = np.arange(lambda_)
            for j in range(lambda_):
                fj = func(x[idx[j]] + mu * (y - x[idx[j]]) / lambda_)
                f[idx[j]] = fj
            idx = np.argsort(f)[:int(np.sqrt(lambda_))]
            f[idx] = fx + 1e-6 * i ** 2
            x[idx] = y[idx]
        return x

    sa_budget = budget // 2
    cma_es_budget = budget - sa_budget
    x_sa = sa_search(sa_budget)
    x_cma_es = cma_es_search(cma_es_budget)

    if func(x_cma_es) < func(x_sa):
        return x_cma_es
    else:
        return x_sa

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.maximum(np.minimum(x, ub), lb)

    x = np.zeros(dim)
    temp = 1.0
    T_min = 1e-6
    for t in range(1, budget + 1):
        delta = rng.uniform(-1, 1, dim) * temp
        new_x = clip(x + delta)
        epsilon = func(new_x) - func(x)
        if epsilon <= 0 or np.exp(-epsilon / temp) > rng.rand():
            x = new_x
        if t % (budget // 10) == 0:
            temp *= 0.99
        if temp < T_min:
            break
    return clip(x)

